export const SlotView = z.object({
  card_id: z.string(), under: z.array(z.string()), energies: z.array(z.string()),
  tools: z.array(z.string()), damage: z.number().int(), hp_max: z.number().int(),
  conditions: z.array(Condition), turn_effects: z.array(TurnEffect), markers: z.array(z.string()),
  prize_value: z.number().int(),
});
export const PlayerBoard = z.object({
  active: SlotView.nullable(), bench: z.array(SlotView),
  hand: z.union([z.array(z.string()), z.number().int()]),   // cards, or a count from the other perspective
  deck: z.number().int(), discard: z.array(z.string()), lost_zone: z.array(z.string()),
  prizes: z.number().int(), supporter_played: z.boolean(),
});
export const ViewState = z.object({
  i: z.number().int(), turn: z.number().int(), current: z.number().int().min(0).max(1),
  phase: GamePhase, stadium: z.object({ card_id: z.string(), owner: z.number().int() }).nullable(),
  p: z.tuple([PlayerBoard, PlayerBoard]),
  pending_prompt: PromptView.nullable(),
  last_damage: DamageCalc.nullable(),          // the pipeline breakdown of S04.T07, so the board can explain a number
  outcome: z.object({ winner: z.number().nullable(), reason: EndReason }).nullable(),
});

let mod: Promise<typeof import("./pkg/ptcg_wasm")> | null = null;
export function loadEngine() { return (mod ??= import("./pkg/ptcg_wasm").then(async m => { await m.default(); return m; })); }
export const WASM_SIZE_BUDGET_KB = 600;
export const REPLAY_SPEED_MS = 600;

export type MatchMode = "printing" | "reprint" | "none";
export type Verdict =
  | { kind: "agree";        checkpoints: number }
  | { kind: "disagree";     step: number; field: string; ours: unknown; theirs: unknown }
  | { kind: "inconclusive"; reason: "unmatched" | "unanswerable_prompt" | "unsupported_setup"
                                  | "twinleaf_error" | "no_codes"; detail: string };

export interface ObservedSlot {
  card_id: string; under: string[]; energies: string[]; tools: string[];   // multisets, sorted
  damage: number; conditions: ("asleep"|"paralyzed"|"confused"|"poisoned"|"burned")[];   // sorted
}
export interface ObservedPlayer {
  active: ObservedSlot | null; bench: (ObservedSlot | null)[];
  hand: string[]; discard: string[]; lost_zone: string[];                  // multisets, sorted
  deck_count: number; prizes_remaining: number;
}
export interface ObservedState {
  turn: number; current: 0 | 1;
  p: [ObservedPlayer, ObservedPlayer];
  ended: { winner: 0 | 1 | null; reason: string } | null;
}

export function observeOurs(game: OurGame): ObservedState;
export function observeTwinleaf(state: TwinState, map: CardIdMap): ObservedState;
export function compare(a: ObservedState, b: ObservedState): { equal: boolean; field?: string; a?: unknown; b?: unknown };
export function runOne(ctx: RoundContext, scenario: Scenario): Verdict;

export type Provider = "anthropic" | "groq" | "local" | "stub" | "none";
export interface LlmConfig { provider: Provider; model: string; baseUrl?: string;
  timeoutMs: number; maxRetries: number; maxTokens: number; temperature?: number; }
export interface LlmResponse<T> { data: T | null; text: string; provider: Provider; model: string;
  inputTokens?: number; outputTokens?: number; usedFallbackParse: boolean; }

export function resolveProvider(env?: NodeJS.ProcessEnv): LlmConfig;          // "none" when unconfigured (RN-60)
export function isAvailable(cfg?: LlmConfig): boolean;
export async function complete<T>(cfg: LlmConfig, req: {
  system: string; messages: { role: "user" | "assistant"; content: string }[];
  jsonSchema: object;                      // the emit_result input_schema / response_format schema
  signal?: AbortSignal;
}): Promise<LlmResponse<T>>;
export function extractJson(text: string): unknown | null;
export function retryAfterSeconds(res: { headers: Headers; body: string },
                                  opts?: { default_?: number; cap?: number }): number;  // default 8, cap 90, floor 1
export class LlmError extends Error { provider: Provider; status?: number; retryable: boolean; }
export const RETRY_AFTER_DEFAULT_S = 8;
export const RETRY_AFTER_CAP_S = 90;

export const ProposalItem = z.object({
  code: z.string().regex(/^[A-Z][A-Z0-9_]*$/),          // must exist in rule_codes (BR-S08.T06-01)
  params: z.record(z.unknown()).default({}),            // validated by validateParams (RN-61)
  sentenceFrom: z.number().int().min(0),
  sentenceTo: z.number().int().min(0),
  why: z.string().max(200),                             // one line per item, for the reviewer
});
export const Proposal = z.object({
  items: z.array(ProposalItem).max(12),                 // an empty list is a legitimate "I cannot classify this"
  rationale: z.string().max(1000),
  confidence: z.enum(["high", "medium", "low"]),
  unsupported: z.boolean().default(false),              // the text needs a code that does not exist
});
export const PROPOSAL_PROMPT_VERSION = 1;
